mapper.select:
SELECT biz_orders.id, biz_orders.repo_id, biz_orders.user_id, user.username AS user_name, dep.name AS department_name, pro.name AS product_name, biz_orders.quantity, biz_orders.unit_price, biz_orders.total_amount, biz_orders.order_date, biz_orders.create_by, biz_orders.create_time, biz_orders.update_by, biz_orders.update_time FROM biz_orders left join biz_repository rep on rep.id = biz_orders.repo_id left join sys_dept dep on rep.department_id = dep.id left join biz_products pro on rep.product_id = pro.id left join sys_user user on biz_orders.user_id = user.id
WHERE rep.department_id IN
#{item}
WHERE biz_orders.user_id = #{queryParams.userId}
